def getIndexMemberDaily(stockDaily, indexWeight, indexCode, startDate, endDate){

    // 1. 获取该指数截止 endDate 的所有调仓日
    rebalanceDays = select distinct trade_date from indexWeight where index_code = indexCode and trade_date <= endDate order by trade_date

    // 2. 获取行情区间内实际存在的交易日
    dailyDates = select distinct trade_date from stockDaily where trade_date between startDate : endDate order by trade_date

    // 3. 每个交易日映射到最近一次调仓日
    dateMap = aj(dailyDates, rebalanceDays, `trade_date)
    dateMap.rename!(`trade_date`rebalance_date)

    dateMap = select trade_date, rebalance_date from dateMap where not isNull(rebalance_date)

    // 4. 仅保留本次查询涉及到的调仓日快照
    validRebalanceDates = exec distinct rebalance_date from dateMap

    members = select con_code, trade_date as rebalance_date from indexWeight where index_code = indexCode and trade_date in validRebalanceDates

    // 5. 构造候选股票池以减少行情扫描范围
    candidateCodes = exec distinct con_code from members

    dailySub = select code, trade_date, open, high, low, close, pre_close, change, pct_chg, vol, amount from stockDaily where trade_date between startDate : endDate and code in candidateCodes

    // 6. 给行情挂上 rebalance_date
    dailyWithRebalance = select a.code, a.trade_date, a.open, a.high, a.low, a.close, a.pre_close, a.change, a.pct_chg, a.vol, a.amount, d.rebalance_date from dailySub a join dateMap d on a.trade_date = d.trade_date

    // 7. 精确过滤属于该调仓快照的股票
    return select s.code, s.trade_date, s.open, s.high, s.low, s.close, s.pre_close, s.change, s.pct_chg, s.vol, s.amount from dailyWithRebalance s join members m on s.code = m.con_code and s.rebalance_date = m.rebalance_date order by s.trade_date, s.code
}
